import type { BankQuestion } from "@/lib/bank";

/** Grammar and Error Spotting (English): 174 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eng-grammar-1","question":"He has been working here ___ 2015.","options":["for","since","from","by"],"answer":1,"explanation":"“Since” is used with a point in time.","difficulty":"easy"},
  {"id":"eng-grammar-2","question":"She ___ to school every day.","options":["go","goes","going","gone"],"answer":1,"explanation":"A singular subject in the simple present takes “goes”.","difficulty":"easy"},
  {"id":"eng-grammar-3","question":"He is ___ honest man.","options":["a","an","the","no article"],"answer":1,"explanation":"“Honest” begins with a vowel sound (the h is silent), so it takes “an”.","difficulty":"easy"},
  {"id":"eng-grammar-4","question":"Neither of the boys ___ present.","options":["were","are","was","have been"],"answer":2,"explanation":"“Neither of” takes a singular verb.","difficulty":"moderate"},
  {"id":"eng-grammar-5","question":"One of my friends ___ a doctor.","options":["are","is","were","have"],"answer":1,"explanation":"The subject is “one”, which is singular.","difficulty":"moderate"},
  {"id":"eng-grammar-6","question":"The news ___ very shocking.","options":["are","were","is","have been"],"answer":2,"explanation":"“News” is an uncountable noun and takes a singular verb.","difficulty":"moderate"},
  {"id":"eng-grammar-7","question":"Choose the correctly spelt word.","options":["Acommodate","Accomodate","Accommodate","Acomodate"],"answer":2,"explanation":"Accommodate has double c and double m.","difficulty":"hard"},
  {"id":"eng-grammar-8","question":"Each of the students ___ given a prize.","options":["were","was","have","are"],"answer":1,"explanation":"“Each of” takes a singular verb.","difficulty":"hard"},
  {"id":"eng-grammar-9","question":"Spot the error: “He is senior than me in the office.”","options":["He is","senior than","me in","the office"],"answer":1,"explanation":"Senior, junior, superior and inferior take “to”, not “than”: senior to me.","difficulty":"hard"},
  {"id":"eng-grammar-10","question":"Choose the correct sentence.","options":["I have seen him yesterday.","I saw him yesterday.","I had seen him yesterday.","I have been seeing him yesterday."],"answer":1,"explanation":"A definite past time (“yesterday”) takes the simple past, not the present perfect.","difficulty":"very-hard"},
  {"id":"eng-grammar-11","question":"Hardly had he left the house ___ it started raining.","options":["than","when","then","that"],"answer":1,"explanation":"“Hardly … when” and “No sooner … than” are the correct pairs.","difficulty":"very-hard"},
  {"id":"eng-grammar-12","question":"Which of the following words is spelt correctly?","options":["Occurence","Occurrence","Ocurrence","Occurrance"],"answer":1,"explanation":"Occurrence has double c and double r.","difficulty":"very-hard"},
  {"id":"eng-grammar-13","question":"Fill in the blank: She has been working here ____ 2015.","options":["for","since","from","by"],"answer":1,"explanation":"“Since” marks a point of time; “for” marks a duration.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"eng-grammar-14","question":"Spot the error: One of my friends (a) / are going (b) / to Delhi tomorrow. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"“One of my friends” is singular: “is going”.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-15","question":"Choose the correct passive form: “They are building a new bridge.”","options":["A new bridge is built by them.","A new bridge is being built by them.","A new bridge was built by them.","A new bridge has been built by them."],"answer":1,"explanation":"Present continuous active → “is/are being + past participle” in the passive.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-16","question":"Spot the error: Neither of the two boys (a) / have submitted (b) / their homework. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"“Neither of” takes a singular verb: “has submitted his homework”.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-17","question":"Choose the correct indirect speech: He said, “I am going to the market now.”","options":["He said that he is going to the market now.","He said that he was going to the market then.","He said that he was going to the market now.","He told that he is going to the market then."],"answer":1,"explanation":"Tense shifts back (am → was) and “now” becomes “then”.","difficulty":"hard","source":"SSC CGL · SBI PO"},
  {"id":"eng-grammar-18","question":"Spot the error: The number of accidents (a) / on this road (b) / have increased sharply. (c) / No error (d)","options":["a","b","c","d"],"answer":2,"explanation":"“The number of” is singular: “has increased”. (“A number of” would take a plural verb.)","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-19","question":"Spot the error: Scarcely had he reached the station (a) / than the train (b) / started moving. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"“Scarcely” and “hardly” pair with “when”, not “than”.","difficulty":"hard"},
  {"id":"eng-grammar-20","question":"Choose the correct option: “If I ___ a bird, I would fly to you.”","options":["was","were","am","had been"],"answer":1,"explanation":"An imaginary present condition takes the subjunctive “were” for all subjects.","difficulty":"hard"},
  {"id":"eng-grammar-21","question":"Spot the error: He is one of those writers (a) / who has won (b) / several awards this year. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"“Who” refers to “writers” (plural), so it should be “who have won”.","difficulty":"very-hard"},
  {"id":"eng-grammar-22","question":"Choose the correct passive form of: “Who taught you this trick?”","options":["By whom were you taught this trick?","By whom you were taught this trick?","Who was taught this trick by you?","This trick was taught by whom to you?"],"answer":0,"explanation":"Questions keep the question order in the passive: By whom + auxiliary + subject + past participle.","difficulty":"very-hard"},
  {"id":"eng-grammar-23","question":"Spot the error: No sooner did the bell ring (a) / when the students (b) / rushed out of the class. (c) / No error (d)","options":["a","b","c","d"],"answer":1,"explanation":"“No sooner” pairs with “than”, not “when”.","difficulty":"very-hard"},
  {"id":"eng-grammar-24","question":"Choose the correct option: “The committee ___ divided in their opinions.”","options":["was","were","has been","is being"],"answer":1,"explanation":"When members act as individuals (“their opinions”), a collective noun takes a plural verb.","difficulty":"very-hard"},
  {"id":"eng-grammar-25","question":"Spot the part with the error: “Neither the manager nor the employees / was aware / of the new policy.”","options":["Neither the manager nor the employees","was aware","of the new policy","No error"],"answer":1,"explanation":"With neither … nor, the verb agrees with the nearer subject, “employees”, so it should be “were aware”.","difficulty":"very-hard"},
  {"id":"eng-grammar-26","question":"Which sentence is correct?","options":["Scarcely had he left when it started raining.","Scarcely had he left than it started raining.","Scarcely he had left when it started raining.","Scarcely did he left when it started raining."],"answer":0,"explanation":"“Scarcely” and “hardly” take “when”, not “than”, and put the auxiliary before the subject.","difficulty":"very-hard"},
  {"id":"eng-grammar-27","question":"Fill in the blank: “The committee ___ divided in their opinions.”","options":["is","are","was being","has"],"answer":1,"explanation":"When a collective noun’s members act separately (“their opinions”), it takes a plural verb.","difficulty":"very-hard"},
  {"id":"eng-grammar-28","question":"Which sentence has NO error?","options":["Each of the players have given their best.","One of my friend is a doctor.","Neither of the answers is correct.","The sceneries of Kashmir is beautiful."],"answer":2,"explanation":"“Neither of” takes a singular verb. The others need “has given his best”, “one of my friends” and “the scenery … is” (scenery is uncountable).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-29","question":"Spot the part with the error: “The principal, along with the teachers, / were present / at the function.”","options":["The principal, along with the teachers,","were present","at the function","No error"],"answer":1,"explanation":"Words joined by “along with”, “as well as” or “together with” do not change the number of the subject: “the principal … was present”.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-30","question":"Fill in the blank: She ___ her homework before dinner yesterday.","options":["finishes","finished","finish","finishing"],"answer":1,"explanation":"'Yesterday' fixes the time in the past, so the simple past 'finished' is needed.","difficulty":"easy","source":"SSC GD · RRB Group D"},
  {"id":"eng-grammar-31","question":"Fill in the blank: ___ apple a day keeps the doctor away.","options":["A","The","An","No article"],"answer":2,"explanation":"'Apple' begins with a vowel sound, so the indefinite article is 'an'.","difficulty":"easy","source":"SSC GD · SSC CHSL"},
  {"id":"eng-grammar-32","question":"Fill in the blank: The children ___ playing in the park.","options":["is","am","was","are"],"answer":3,"explanation":"'Children' is plural, so the plural present verb 'are' is required.","difficulty":"easy","source":"SSC GD · RRB NTPC"},
  {"id":"eng-grammar-33","question":"Spot the error: Mathematics (a) / are (b) / my favourite subject. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"Names of subjects ending in -s (mathematics, physics, economics) are singular: 'Mathematics is my favourite subject'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-34","question":"Fill in the blank: He is good ___ mathematics.","options":["in","at","with","on"],"answer":1,"explanation":"The fixed preposition after 'good' for a skill or subject is 'at': good at mathematics. 'Good in' is a common Indian-English error.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eng-grammar-35","question":"Spot the error: The furnitures (a) / in this room (b) / are very old. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Furniture' is an uncountable noun and has no plural: 'The furniture in this room is very old' (so the verb changes to 'is' as well, but the error lies in part (a)).","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-36","question":"Fill in the blank: I have known him ___ ten years.","options":["since","from","during","for"],"answer":3,"explanation":"'For' goes with a length of time (ten years); 'since' needs a point of time (since 2015).","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"eng-grammar-37","question":"Improve the underlined part: He has returned back from Delhi.","options":["has returned","had returned back","returned back","No improvement"],"answer":0,"explanation":"'Return' already means 'come back', so 'returned back' is a redundancy. 'He has returned from Delhi' is correct.","difficulty":"moderate","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-38","question":"Spot the error: She is (a) / more smarter (b) / than her sister. (c) / No error (d)","options":["(c)","(b)","(a)","(d)"],"answer":1,"explanation":"'Smarter' is already comparative; adding 'more' makes a double comparative. Use 'smarter than'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-39","question":"Spot the error: The police (a) / has arrested (b) / the thief. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Police' is a plural noun (like 'people' and 'cattle') and takes a plural verb: 'The police have arrested the thief'.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-40","question":"Fill in the blank: Unless you ___ hard, you will not pass.","options":["work","will work","worked","do not work"],"answer":0,"explanation":"'Unless' means 'if … not' and takes the simple present, not 'will'. 'Unless you do not work' doubles the negative.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-41","question":"Improve the underlined part: No sooner did he see the police when he ran away.","options":["then he ran away","as he ran away","than he ran away","No improvement"],"answer":2,"explanation":"'No sooner' is a comparative and must be followed by 'than', not 'when' or 'then'.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-42","question":"Spot the error: Many a student (a) / have failed (b) / in the examination. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Many a' is followed by a singular noun and a singular verb, even though the meaning is plural: 'Many a student has failed'.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-43","question":"Fill in the blank: I would rather die ___ beg.","options":["then","to","than","but"],"answer":2,"explanation":"'Would rather' expresses preference and is followed by 'than' (not 'then' or 'to'): rather die than beg.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-44","question":"Spot the error: He insisted (a) / to go (b) / to the party. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Insist' takes 'on' + gerund, not an infinitive: 'He insisted on going to the party'.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-45","question":"Change into the active voice: Let the door be closed.","options":["Let the door close.","Close the door.","Someone closes the door.","The door closes."],"answer":1,"explanation":"'Let + object + be + past participle' is the passive of an imperative. Its active form is the plain imperative: 'Close the door.'","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-46","question":"Spot the error: She likes (a) / singing, dancing (b) / and to paint. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"Items in a list must be parallel. 'Singing, dancing' are gerunds, so the third must be 'painting', not the infinitive 'to paint'.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"eng-grammar-47","question":"Change into indirect speech: She said to me, “Do you like tea?”","options":["She asked me that I liked tea.","She asked me do I like tea.","She asked me if I like tea.","She asked me if I liked tea."],"answer":3,"explanation":"A yes/no question becomes 'asked … if/whether', the question order becomes statement order, and the present 'like' shifts to the past 'liked' after the past reporting verb.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-48","question":"Spot the error: Either the students (a) / or the teacher (b) / are responsible for the mess. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"With 'either … or' the verb agrees with the nearer subject. 'The teacher' is nearer and singular, so it should be 'is responsible'. The plural 'students' earlier in the sentence is the trap.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-49","question":"Spot the error: The sceneries (a) / of Kashmir (b) / are breathtaking. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Scenery' is uncountable and has no plural form: 'The scenery of Kashmir is breathtaking'. The error is the noun in part (a).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-50","question":"Spot the error: One of the most (a) / important question (b) / was left unanswered. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'One of the' is followed by a plural noun: 'one of the most important questions'. The singular verb 'was' is correct because the subject is 'one'.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-51","question":"Improve the underlined part: If I would have known, I would have helped you.","options":["If I knew","Had I have known","If I had known","No improvement"],"answer":2,"explanation":"A third conditional uses the past perfect in the if-clause: 'If I had known, I would have helped'. 'Would have' belongs only in the main clause.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-52","question":"Spot the error: He is (a) / the most unique (b) / artist of his time. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Unique' is an absolute adjective meaning 'one of a kind' and cannot be graded: 'the most unique' should be 'a unique' or 'the most unusual'.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-grammar-53","question":"Fill in the blank: The teacher, as well as the students, ___ invited.","options":["were","was","are","have been"],"answer":1,"explanation":"With 'as well as', 'along with' or 'together with', the verb agrees with the first subject only. 'The teacher' is singular, so 'was invited'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-54","question":"Spot the error: The two brothers (a) / do not talk (b) / to one another. (c) / No error (d)","options":["(d)","(a)","(c)","(b)"],"answer":2,"explanation":"'Each other' is used for two persons and 'one another' for more than two. With 'the two brothers' it should be 'to each other'.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"eng-grammar-55","question":"Spot the error: She prefers (a) / coffee more than (b) / tea. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Prefer' is followed by 'to', never by 'more than': 'She prefers coffee to tea'.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"eng-grammar-56","question":"Improve the underlined part: He ordered for a cup of coffee.","options":["ordered to a cup of coffee","No improvement","ordered a cup of coffee","ordered about a cup of coffee"],"answer":2,"explanation":"'Order' takes a direct object without a preposition: 'He ordered a cup of coffee'. 'Order for' is a common Indian-English error.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-57","question":"Spot the error: Being a rainy day, (a) / we decided (b) / to stay at home. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"The participle 'being' has no subject and wrongly attaches to 'we' (a dangling modifier). Correct: 'It being a rainy day, we decided to stay at home'.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"eng-grammar-58","question":"Change into the passive voice: The teacher will have finished the lesson by noon.","options":["The lesson will be finished by the teacher by noon.","The lesson will have finished by noon.","The lesson will have been finished by the teacher by noon.","The lesson would have been finished by the teacher by noon."],"answer":2,"explanation":"Future perfect active 'will have finished' becomes 'will have been finished' in the passive. Dropping 'been' or changing to 'will be' alters the tense.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eng-grammar-59","question":"Spot the error: I have seen him (a) / yesterday (b) / at the station. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"The present perfect cannot be used with a definite past time like 'yesterday'. The verb in part (a) should be the simple past: 'I saw him yesterday'.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id": "eng-grammar-60", "question": "Fill in the blank: The sun ___ in the east.", "options": ["rose", "rises", "is rising", "rise"], "answer": 1, "explanation": "Universal truths take the simple present: 'The sun rises in the east.' A singular subject takes 'rises', not 'rise'.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-61", "question": "Fill in the blank: She is fond ___ music.", "options": ["of", "with", "for", "in"], "answer": 0, "explanation": "'Fond' always takes the preposition 'of': fond of music.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-62", "question": "Spot the error: He did not knew (a) / the answer (b) / to the question. (c) / No error (d)", "options": ["(b)", "(c)", "(d)", "(a)"], "answer": 3, "explanation": "After the auxiliary 'did', the main verb takes its base form: 'He did not know'. 'Did not knew' marks the past twice.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-63", "question": "Fill in the blank: Each boy and each girl ___ given a book.", "options": ["were", "are", "was", "have been"], "answer": 2, "explanation": "When two singular subjects joined by 'and' are each preceded by 'each' or 'every', the verb is singular: 'was given'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-64", "question": "Fill in the blank: Neither Ram nor his friends ___ come yet.", "options": ["has", "have", "is", "was"], "answer": 1, "explanation": "With 'neither … nor' the verb agrees with the nearer subject. 'Friends' is plural, so 'have come'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-65", "question": "Change into the passive voice: Open the window.", "options": ["Let the window be opened.", "The window is opened.", "The window should open.", "Let the window open."], "answer": 0, "explanation": "An imperative becomes passive with 'Let + object + be + past participle': 'Let the window be opened.'", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-66", "question": "Spot the error: I am looking forward (a) / to meet you (b) / next week. (c) / No error (d)", "options": ["(a)", "(c)", "(d)", "(b)"], "answer": 3, "explanation": "In 'look forward to', 'to' is a preposition, so it takes a gerund: 'to meeting you'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-67", "question": "Spot the error: The quality of the mangoes (a) / were not (b) / up to the mark. (c) / No error (d)", "options": ["(a)", "(c)", "(b)", "(d)"], "answer": 2, "explanation": "The subject is 'quality' (singular); 'of the mangoes' only describes it. So 'was not', not 'were not'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-68", "question": "Change into indirect speech: He said, “I have finished my work.”", "options": ["He said that he has finished his work.", "He said that he had finished his work.", "He said that I had finished my work.", "He said that he finished his work."], "answer": 1, "explanation": "With a past reporting verb, the present perfect 'have finished' moves back to past perfect 'had finished', and 'I/my' become 'he/his'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-69", "question": "Spot the error: Unless you do not work hard (a) / you will not (b) / pass. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Unless' already means 'if not', so 'unless you do not' is a double negative. Correct: 'Unless you work hard, you will not pass.'", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-70", "question": "Fill in the blank: Ten kilometres ___ a long distance to walk.", "options": ["are", "were", "have been", "is"], "answer": 3, "explanation": "A plural amount of distance, money or time treated as one whole takes a singular verb: 'Ten kilometres is a long distance.'", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-71", "question": "Spot the error: He is taller (a) / than any boy (b) / in the class. (c) / No error (d)", "options": ["(a)", "(c)", "(b)", "(d)"], "answer": 2, "explanation": "He is himself a boy in the class, so he must be compared with the others: 'than any other boy'. Otherwise he is compared with himself.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-72", "question": "Fill in the blank: Had she studied harder, she ___ the examination.", "options": ["would pass", "would have passed", "will have passed", "had passed"], "answer": 1, "explanation": "'Had she studied' is the inverted past-perfect condition (third conditional), so the result clause takes 'would have + past participle'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-73", "question": "Spot the error: The cattle (a) / is grazing (b) / in the field. (c) / No error (d)", "options": ["(b)", "(a)", "(c)", "(d)"], "answer": 0, "explanation": "'Cattle' is always plural, so it takes 'are grazing'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-74", "question": "Spot the error: Not only the students (a) / but also the teacher (b) / were punished. (c) / No error (d)", "options": ["(a)", "(b)", "(d)", "(c)"], "answer": 3, "explanation": "With 'not only … but also' the verb agrees with the nearer subject, 'the teacher' (singular): 'was punished'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-75", "question": "Change into the passive voice: People believe that he is honest.", "options": ["He was believed to be honest.", "It is believed by people he is honest.", "He is believed to be honest.", "He is believed being honest."], "answer": 2, "explanation": "'People believe that X is …' becomes 'X is believed to be …', keeping the present tense. 'Was believed' changes the tense.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-76", "question": "Change into indirect speech: She said to him, “Please wait here till I return.”", "options": ["She told him to please wait here till she returns.", "She requested him to wait there till she returned.", "She requested him that he waits there till she returned.", "She ordered him to wait here till she returned."], "answer": 1, "explanation": "'Please' becomes the reporting verb 'requested' + infinitive. 'Here' becomes 'there' and 'return' moves back to 'returned'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-77", "question": "Spot the error: Despite of (a) / his illness, (b) / he attended the meeting. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Despite' never takes 'of'. Say 'despite his illness' or 'in spite of his illness'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-78", "question": "Spot the error: It is high time (a) / we leave (b) / for the station. (c) / No error (d)", "options": ["(a)", "(c)", "(d)", "(b)"], "answer": 3, "explanation": "'It is high time' is followed by the past subjunctive: 'It is high time we left.' The present form is the usual slip.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-79", "question": "Which sentence is grammatically correct?", "options": ["Bread and butter are my staple breakfast.", "Physics are my favourite subject.", "The Prime Minister, along with his ministers, has arrived.", "Every man and woman were present."], "answer": 2, "explanation": "A subject joined by 'along with' keeps its own number, so 'The Prime Minister … has arrived' is right. 'Bread and butter' is one dish (is), 'Physics' is singular (is), and 'every … and …' takes 'was'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-80", "question": "Fill in the blank: He talks as if he ___ the owner of the house.", "options": ["is", "were", "was being", "has been"], "answer": 1, "explanation": "'As if' for something untrue takes the past subjunctive 'were' for all persons: 'as if he were the owner'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-81", "question": "Spot the error: The reason why he failed (a) / is because (b) / he did not study. (c) / No error (d)", "options": ["(b)", "(a)", "(c)", "(d)"], "answer": 0, "explanation": "'The reason … is because' repeats the idea of cause. Correct: 'The reason why he failed is that he did not study.'", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-82", "question": "Spot the error: My brother-in-laws (a) / are coming (b) / to stay with us. (c) / No error (d)", "options": ["(b)", "(c)", "(d)", "(a)"], "answer": 3, "explanation": "In compound nouns the main word takes the plural: 'brothers-in-law', not 'brother-in-laws'.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-83", "question": "Change into the passive voice: Did they complete the project on time?", "options": ["Was the project being completed by them on time?", "Has the project been completed by them on time?", "Was the project completed by them on time?", "Did the project complete by them on time?"], "answer": 2, "explanation": "A simple-past question with 'did' becomes 'Was/Were + subject + past participle': 'Was the project completed by them on time?'", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-84", "question": "Change into indirect speech: He said, “Let us go for a walk.”", "options": ["He said that let us go for a walk.", "He suggested that they should go for a walk.", "He ordered them to go for a walk.", "He suggested that we should go for a walk."], "answer": 1, "explanation": "'Let us' expressing a proposal becomes 'suggested/proposed that they should …'. 'Us' changes to 'they'; 'ordered' changes the meaning.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-85", "question": "Fill in the blank: She is ___ European.", "options": ["an", "the", "no article", "a"], "answer": 3, "explanation": "Use 'a' because European begins with a 'yoo' (consonant) sound, even though it starts with a vowel letter.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-86", "question": "Fill in the blank: Would you mind ___ the door?", "options": ["closed", "close", "to close", "closing"], "answer": 3, "explanation": "'Mind' is followed by the -ing form: 'Would you mind closing the door?'", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-87", "question": "Fill in the blank: The scissors ___ on the table.", "options": ["was", "has been", "is", "are"], "answer": 3, "explanation": "'Scissors' is a plural-only noun (like trousers, spectacles), so it takes a plural verb: are.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "eng-grammar-88", "question": "Spot the error: This plan will fail, (a) / and it is a secret (b) / between you and I. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "A preposition takes the object form of a pronoun: 'between you and me'. 'I' is the subject form.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-89", "question": "Fill in the blank: I am used to ___ up early.", "options": ["got", "have got", "get", "getting"], "answer": 3, "explanation": "In 'be used to', 'to' is a preposition, so the -ing form follows: 'I am used to getting up early'. Compare 'I used to get up early' (past habit).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-90", "question": "Spot the error: My cousin is (a) / married with (b) / a doctor from Pune. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "One is married to a person, not 'with': 'married to a doctor'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-91", "question": "Fill in the blank: He was accused ___ theft.", "options": ["of", "about", "for", "with"], "answer": 0, "explanation": "The fixed preposition is 'accused of'. Compare 'charged with theft'.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "eng-grammar-92", "question": "Spot the error: All the new (a) / equipments in the lab (b) / are kept locked. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Equipment' is uncountable and has no plural: 'All the new equipment in the lab is kept locked'.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-93", "question": "Choose the correct question tag: Nobody called while I was out, ___?", "options": ["didn't he", "did he", "didn't they", "did they"], "answer": 3, "explanation": "'Nobody' makes the sentence negative, so the tag is positive; indefinite pronouns like nobody take 'they' in tags: 'did they?'", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-94", "question": "Spot the error: The members of the committee (a) / discussed about (b) / the problem at length. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Discuss' takes a direct object; 'about' is redundant: 'discussed the problem'. (The noun form does take it: 'a discussion about'.)", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-95", "question": "Fill in the blank: Walk carefully lest you ___.", "options": ["should fall", "will fall", "would fall", "may not fall"], "answer": 0, "explanation": "'Lest' is followed by 'should' + base verb (or the bare subjunctive), never by 'will' and never by 'not', since lest already means 'in case … not'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-96", "question": "Spot the error: In every society, (a) / the poor is (b) / often neglected. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'The + adjective' (the poor, the rich) refers to a group of people and is plural: 'the poor are often neglected'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-97", "question": "Spot the error: He enjoyed (a) / at the party (b) / last night. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Enjoy' needs an object; with no other object it takes a reflexive pronoun: 'He enjoyed himself at the party'.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "eng-grammar-98", "question": "Spot the error: The harder you practise (a) / for the match, (b) / more confident you will become. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "The double comparative needs 'the' in both halves: 'The harder you practise …, the more confident you will become'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-99", "question": "Spot the error: When the chance came, (a) / he availed of (b) / the opportunity to meet the minister. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Avail' in this sense needs a reflexive pronoun: 'he availed himself of the opportunity'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-100", "question": "Fill in the blank: You had better ___ a doctor.", "options": ["consulted", "to consult", "consulting", "consult"], "answer": 3, "explanation": "'Had better' is followed by the bare infinitive: 'You had better consult a doctor'.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "eng-grammar-101", "question": "Spot the error: I am sure that hardly anyone (a) / in this village (b) / has never seen a tiger. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "'Hardly' is already negative, so 'never' makes a double negative. Use 'has ever seen a tiger'.", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-102", "question": "Spot the error: The new house has a garden (a) / and it (b) / comprises of four bedrooms. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "'Comprise' means 'consist of' and takes no 'of': 'it comprises four bedrooms' (or 'consists of four bedrooms').", "difficulty": "hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-103", "question": "Spot the error: Whom do you think (a) / is the best candidate (b) / for the post? (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Do you think' is a parenthetical insert; the pronoun is the subject of 'is', so it must be 'Who': 'Who do you think is the best candidate?'", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-104", "question": "Spot the error: What will you do (a) / supposing if (b) / it rains tomorrow? (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "'Supposing' already means 'if', so 'supposing if' is redundant. Use 'supposing it rains' or 'if it rains'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-105", "question": "Spot the error: One should always (a) / try to do (b) / his duty honestly. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 2, "explanation": "When the subject is 'one', the possessive that follows should be 'one's': 'One should always try to do one's duty honestly'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-106", "question": "Spot the error: The murderer was hung (a) / at dawn (b) / after the trial. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "For execution by hanging, the past participle is 'hanged': 'The murderer was hanged'. 'Hung' is used for objects (the picture was hung).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-107", "question": "Choose the correct question tag: Let's go for a walk, ___?", "options": ["shall we", "don't we", "won't we", "will you"], "answer": 0, "explanation": "A suggestion with 'Let's' (let us) takes the tag 'shall we?'. 'Will you?' is the tag for a request or order beginning with 'Let' (Let me go, will you?).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-108", "question": "Spot the error: Scarcely had the guests arrived (a) / when the lights (b) / went out. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 3, "explanation": "The sentence is correct: 'scarcely' (like 'hardly') pairs with 'when', with the inverted 'had the guests arrived'. 'Than' is used only with 'no sooner'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-109", "question": "Improve the sentence: He is too weak that he cannot walk.", "options": ["too weak that he could not walk", "so weak that he cannot walk", "very weak that he cannot walk", "No improvement"], "answer": 1, "explanation": "'Too' pairs with 'to' (too weak to walk) and 'so' pairs with 'that' (so weak that he cannot walk). 'Too … that' mixes the two patterns.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-110", "question": "Spot the error: Feeling unwell, (a) / he has laid in bed (b) / all morning. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 1, "explanation": "The intransitive verb 'lie' (lie, lay, lain) is needed: 'he has lain in bed'. 'Laid' belongs to the transitive 'lay' (to put something down).", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-111", "question": "Fill in the blank: It is I who ___ to blame.", "options": ["was", "is", "am", "are"], "answer": 2, "explanation": "In a relative clause the verb agrees with the antecedent of 'who', which here is 'I': 'It is I who am to blame'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-112", "question": "How many of these sentences are grammatically correct? 1. The jury has given its verdict. 2. The cattle are grazing in the field. 3. Mathematics is my favourite subject. 4. The news are good.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1 is correct (the jury acting as one body), 2 is correct (cattle is always plural) and 3 is correct (mathematics is singular). 4 is wrong: 'news' is uncountable, so 'The news is good'. Only three.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-113", "question": "Spot the error: Not only he sang (a) / but also danced (b) / at the function. (c) / No error (d)", "options": ["(a)", "(b)", "(c)", "(d)"], "answer": 0, "explanation": "'Not only … but also' must join parallel parts. With 'danced' after 'but also', 'not only' must come before 'sang': 'He not only sang but also danced'.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id": "eng-grammar-114", "question": "Choose the correct indirect speech: He said, “What a beautiful day it is!”", "options": ["He exclaimed that it was a very beautiful day.", "He said that what a beautiful day it was.", "He exclaimed what a beautiful day it is.", "He asked what a beautiful day it was."], "answer": 0, "explanation": "An exclamation is reported with a verb like 'exclaimed', 'what a' becomes 'very', and the tense shifts back (is → was). 'Asked' is for questions.", "difficulty": "very-hard", "source": "SSC CGL · CDS"},
  {"id":"eng-grammar-115","question":"Spot the error: He did not attend the meeting (a) / because of he was (b) / unwell. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Because of' is a preposition and must be followed by a noun ('because of his illness'). Before a clause ('he was unwell') the conjunction 'because' is needed.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-116","question":"Fill in the blank: If it ___ tomorrow, the match will be postponed.","options":["would rain","will rain","rains","rained"],"answer":2,"explanation":"In a first conditional, the if-clause takes the simple present and the main clause takes 'will': 'If it rains, the match will be postponed'. 'Will rain' in the if-clause is the common error.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-117","question":"Choose the correct question tag: He has gone to Delhi, ___?","options":["doesn't he","didn't he","isn't he","hasn't he"],"answer":3,"explanation":"A positive statement takes a negative tag with the same auxiliary: 'has' → 'hasn't he'.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-118","question":"Fill in the blank: She plays ___ violin beautifully.","options":["a","the","an","no article"],"answer":1,"explanation":"The definite article is used before musical instruments when we speak of playing them: 'plays the violin'. (Games, by contrast, take no article: 'plays cricket'.)","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-119","question":"Spot the error: She has been suffering (a) / from fever (b) / for the last Monday. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"A point of time takes 'since': 'since last Monday'. 'For' is used with a period of time ('for three days').","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-120","question":"Change into indirect speech: He said to me, “Don't make a noise.”","options":["He told me not to make a noise.","He told me that don't make a noise.","He said to me that I did not make a noise.","He asked me that I should not made a noise."],"answer":0,"explanation":"A negative imperative is reported with 'told/ordered + object + not to + verb': 'He told me not to make a noise'.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-121","question":"Spot the error: By the time the fire brigade arrived, (a) / the whole building (b) / has been gutted. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"The earlier of two past actions takes the past perfect: 'had been gutted'. The present perfect cannot follow a past-time clause like 'by the time ... arrived'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-122","question":"Spot the error: He told me that (a) / he will meet me (b) / at the station the next day. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"After a past reporting verb ('told'), 'will' changes to 'would': 'he would meet me'. 'The next day' already shows the shift into reported speech.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-123","question":"Spot the error: The teacher said that (a) / the earth moved (b) / round the sun. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"A universal truth keeps the present tense even after a past reporting verb: 'the earth moves round the sun'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-124","question":"Spot the error: He is (a) / an university professor (b) / of great repute. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'University' begins with a 'yoo' (consonant) sound, so it takes 'a': 'a university professor'. The article depends on sound, not spelling.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-125","question":"Spot the error: Though he is rich, (a) / but he is not happy (b) / at all. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Though' is not paired with 'but'. Either drop 'but' or use 'yet': 'Though he is rich, he is not happy' / 'Though he is rich, yet he is not happy'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-126","question":"Spot the error: He made me (a) / to understand (b) / the problem clearly. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"In the active voice 'make' takes the bare infinitive: 'made me understand'. 'To' appears only in the passive ('I was made to understand').","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-127","question":"Fill in the blank: Neither he nor I ___ going to the wedding.","options":["are","am","is","were"],"answer":1,"explanation":"With 'neither ... nor', the verb agrees with the nearer subject, here 'I': 'Neither he nor I am going'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-128","question":"Fill in the blank: I agree ___ your proposal, but I do not agree ___ you on every point.","options":["to, with","with, to","with, with","on, to"],"answer":0,"explanation":"We agree TO a proposal, plan or suggestion, but agree WITH a person (or an opinion).","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-129","question":"Fill in the blank: Many people in the village died ___ cholera that year.","options":["by","from","of","with"],"answer":2,"explanation":"'Die of' is used with a disease ('died of cholera'); 'die from' is used with an external cause such as a wound or overwork.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-130","question":"Change into the passive voice: Everyone knows him.","options":["He has been known by everyone.","He is known by everyone.","He was known to everyone.","He is known to everyone."],"answer":3,"explanation":"The tense stays simple present ('is known'), and the verb 'know' takes 'to' rather than 'by' in the passive: 'He is known to everyone'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-131","question":"Change into indirect speech: She said, “Will you help me, Mohan?”","options":["She asked Mohan will he help her.","She asked Mohan if he would help her.","She told Mohan that he will help her.","She asked Mohan if he will help me."],"answer":1,"explanation":"A yes/no question is reported with 'asked + if/whether', statement word order, 'will' → 'would' and pronouns adjusted: 'She asked Mohan if he would help her'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-132","question":"Choose the correct question tag: Everybody enjoyed the show, ___?","options":["didn't they","didn't he","did they","wasn't it"],"answer":0,"explanation":"Indefinite pronouns like everybody/everyone take 'they' in the tag; a positive statement in the simple past takes 'didn't': 'didn't they?'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-133","question":"Spot the error: Not until the results were declared (a) / he realised (b) / how badly he had done. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"When a sentence begins with 'Not until ...', the main clause is inverted: 'did he realise'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-134","question":"Spot the error: Seldom we come across (a) / such a dedicated (b) / social worker. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"A negative adverb like 'seldom' at the start of a sentence requires inversion: 'Seldom do we come across ...'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-135","question":"Spot the error: Bread and butter (a) / are (b) / his usual breakfast. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'Bread and butter' names a single dish, so it takes a singular verb: 'Bread and butter is his usual breakfast'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-136","question":"Spot the error: A large number of students (a) / has registered (b) / for the new course. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"'A number of' means 'many' and takes a plural verb: 'have registered'. It is 'THE number of' that takes a singular verb.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-137","question":"Spot the error: She is the most intelligent (a) / of all the other (b) / girls in the class. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"With a superlative, 'other' is wrong because she is included in the group: 'the most intelligent of all the girls'. 'Other' belongs with a comparative ('more intelligent than any other girl').","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-138","question":"Spot the error: No sooner had I opened the door (a) / than the dog (b) / ran out into the street. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"The sentence is correct: 'No sooner' is followed by inversion ('had I opened') and correctly paired with 'than'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-139","question":"Spot the error: Neither of the two candidates (a) / is suitable (b) / for the post. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"The sentence is correct. 'Neither' (of two) is singular and takes 'is'. Changing it to 'are' would be the error.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-140","question":"Spot the error: The boy was so tired (a) / that he could not (b) / hardly walk. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"'Hardly' is already negative, so 'could not hardly' is a double negative. It should be 'he could hardly walk'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-141","question":"Spot the error: Ten years have passed (a) / since he has left (b) / his native village. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"A 'since' clause that marks a point in the past takes the simple past: 'since he left'. The present perfect belongs to the main clause.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-142","question":"Spot the error: The officer asked me (a) / where was I going (b) / so late at night. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":1,"explanation":"In an indirect question the word order is that of a statement: 'where I was going'. Question order ('was I') is used only in direct speech.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-143","question":"Fill in the blank: Were he to apologise sincerely, I ___ him.","options":["forgive","will forgive","would have forgiven","would forgive"],"answer":3,"explanation":"'Were he to ...' is an inverted second conditional ('If he were to apologise'), so the main clause takes 'would + base verb'. 'Would have forgiven' belongs to the third conditional.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-144","question":"Choose the correct question tag: I am right, ___?","options":["am not I","amn't I","aren't I","isn't it"],"answer":2,"explanation":"The standard negative tag for 'I am' is the irregular 'aren't I?'. 'Amn't I' is not accepted in standard English.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-145","question":"Spot the error: Let you and I (a) / go together (b) / to the village fair. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Let' is followed by the object form of the pronoun: 'Let you and me go'. 'I' is a subject pronoun and cannot be the object of 'let'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-146","question":"Spot the error: Hardly I had reached (a) / the office (b) / when the meeting began. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"A sentence opening with 'Hardly' needs inversion: 'Hardly had I reached the office when ...'. 'When' is the correct partner of 'hardly'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-147","question":"Spot the error: Myself and my sister (a) / will attend (b) / the function tomorrow. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"A reflexive pronoun cannot be used as a subject. The correct form is 'My sister and I will attend', with the first person placed last out of courtesy.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-148","question":"Spot the error: Since the exam has been postponed, (a) / you need not (b) / to worry about it now. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"'Need' used as a modal (in 'need not') takes the bare infinitive: 'you need not worry'. 'To' is used only with the ordinary verb: 'you do not need to worry'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-149","question":"Fill in the blank: Two-thirds of the students ___ absent on the day of the strike.","options":["was","has been","is","were"],"answer":3,"explanation":"With fractions, the verb agrees with the noun after 'of'. 'Students' is plural, so 'were'. (Compare: 'Two-thirds of the cake was eaten'.)","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-150","question":"Fill in the blank: A pair of new shoes ___ lying under the bed.","options":["were","are","was","have been"],"answer":2,"explanation":"The subject is 'a pair', which is singular, so the verb is 'was'. 'Shoes' is only the object of the preposition 'of'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-151","question":"Fill in the blank: 'Gulliver's Travels' ___ written by Jonathan Swift.","options":["have been","were","was","are"],"answer":2,"explanation":"The title of a book is treated as singular, even when it looks plural: 'Gulliver's Travels was written by Swift'.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-152","question":"Fill in the blank: He is ___ one-eyed man who sells toys near the temple.","options":["the","an","a","no article"],"answer":2,"explanation":"'One' begins with a 'w' (consonant) sound, so it takes 'a': 'a one-eyed man'. 'An' is the trap, since the word begins with a vowel letter.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-153","question":"Change into the passive voice: Somebody must have stolen my bag.","options":["My bag must be stolen by somebody.","My bag must have been stolen.","My bag must have stolen.","My bag must had been stolen by somebody."],"answer":1,"explanation":"A perfect modal 'must have + V3' becomes 'must have been + V3' in the passive. The agent 'somebody' is usually dropped.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-154","question":"Spot the error: During the holidays (a) / she did nothing (b) / but to complain about the heat. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"After 'do nothing but', the bare infinitive is used: 'did nothing but complain'. 'To' is wrong here.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-155","question":"Spot the error: The secretary and treasurer of the club (a) / has been arrested (b) / for misusing funds. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"There is no error. The article 'the' appears only once, so 'secretary and treasurer' is one person holding two posts, and the singular 'has' is correct. 'The secretary and the treasurer' would mean two people and need 'have'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-156","question":"Spot the error: Of all the boys in the class, (a) / he is the only one (b) / who have passed in every subject. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":2,"explanation":"After 'the only one', the relative pronoun refers to 'one' (singular), so the verb is 'has passed'. In 'one of the boys who have passed' the plural would be correct — but 'the only one' singles him out.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-157","question":"Spot the error: I have been knowing him (a) / since my school days (b) / and trust him completely. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Know' is a stative verb and is not used in continuous tenses: 'I have known him since my school days'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-158","question":"Spot the error: Please explain me (a) / how this machine (b) / works. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Explain' does not take a person as a direct object; it needs 'to': 'Please explain to me how this machine works'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-159","question":"Spot the error: Ram is elder (a) / than his cousin (b) / by two years. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":0,"explanation":"'Elder' is not followed by 'than'; with 'than' we use 'older': 'Ram is older than his cousin'. 'Elder' is used attributively ('my elder brother').","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-160","question":"Spot the error: Each one of the members (a) / was given (b) / a copy of the report. (c) / No error (d)","options":["(a)","(b)","(c)","(d)"],"answer":3,"explanation":"The sentence is correct: the subject is 'each one', which is singular, so 'was given' is right. Changing it to 'were' because of 'members' would be the error.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-161","question":"Fill in the blank: More than one student ___ absent from the class today.","options":["have been","were","are","was"],"answer":3,"explanation":"Although its meaning is plural, 'more than one' + singular noun takes a singular verb: 'More than one student was absent'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-162","question":"Fill in the blank: None of the milk ___ spilt when the jug fell.","options":["were","have been","was","are"],"answer":2,"explanation":"'None' takes the number of the noun it refers to. 'Milk' is uncountable, so the verb is singular: 'None of the milk was spilt'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-163","question":"Fill in the blank: The United States ___ a federal republic.","options":["are","were","have been","is"],"answer":3,"explanation":"The name of a country is singular even when it has a plural form: 'The United States is ...'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-164","question":"Fill in the blank: He was elected ___ chairman of the board last week.","options":["no article","a","an","the"],"answer":0,"explanation":"After verbs like 'elect', 'appoint' or 'make', a title or unique post usually takes no article: 'He was elected chairman'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-165","question":"Choose the correct question tag: Few people know the real story, ___?","options":["do they","don't they","doesn't it","did they"],"answer":0,"explanation":"'Few' (without 'a') is negative in meaning ('hardly any'), so the tag is positive: 'do they?'. 'A few people know ...' would take 'don't they?'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-166","question":"Choose the correct question tag: There is hardly any milk left, ___?","options":["isn't there","is it","is there","isn't it"],"answer":2,"explanation":"'Hardly' makes the statement negative, so the tag is positive; with 'there is' the tag repeats 'there': 'is there?'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-167","question":"Fill in the blank: I'd rather you ___ tomorrow instead of today.","options":["had come","come","will come","came"],"answer":3,"explanation":"'Would rather' + a different subject takes the past (subjunctive) form to refer to the present or future: 'I'd rather you came tomorrow'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-168","question":"Change into the passive voice: He made her dance.","options":["She was being made to dance by him.","She was made dance by him.","She was made to dance by him.","She made to dance by him."],"answer":2,"explanation":"In the active, 'make' takes a bare infinitive ('made her dance'), but in the passive 'to' returns: 'She was made to dance by him'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-169","question":"Change into the passive voice: Who is calling me?","options":["By whom am I called?","By whom am I being called?","Who am I being called by him?","By whom I am being called?"],"answer":1,"explanation":"The present continuous passive is 'am/is/are being + V3', and in a question the auxiliary comes before the subject: 'By whom am I being called?'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-170","question":"Change into the passive voice: It is time to close the shop.","options":["It is time for the shop to be closed.","It is time the shop was closing.","The shop is time to be closed.","It is time to be closed the shop."],"answer":0,"explanation":"The active infinitive 'to close' becomes the passive infinitive 'to be closed', with the object introduced by 'for': 'It is time for the shop to be closed'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-171","question":"Change into indirect speech: The old woman said, “May God bless you, my son!”","options":["The old woman said that God may bless you, my son.","The old woman prayed that God might bless her son.","The old woman prayed to her son that God bless him.","The old woman wished that may God bless her son."],"answer":1,"explanation":"A wish or prayer with 'May' is reported with 'prayed/wished that', 'may' becomes 'might', and the vocative 'my son' is absorbed: 'prayed that God might bless her son'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-172","question":"Change into indirect speech: He said to me, “Where have you been all these days?”","options":["He told me where I have been all those days.","He asked me where had I been all these days.","He asked me where I had been all those days.","He asked me where I was all these days."],"answer":2,"explanation":"Question → 'asked'; statement word order; present perfect → past perfect ('had been'); 'these' → 'those'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-173","question":"Improve the sentence: She not only plays the piano but also the guitar.","options":["No improvement","She not only plays the piano but also plays guitar also.","Not only she plays the piano but also the guitar.","She plays not only the piano but also the guitar."],"answer":3,"explanation":"Correlatives must join parallel parts. 'The piano' and 'the guitar' are both objects of 'plays', so 'not only' should come just before 'the piano'. 'Not only she plays' would need inversion ('Not only does she play').","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"},
  {"id":"eng-grammar-174","question":"Fill in the blank: If he had taken the medicine yesterday, he ___ better now.","options":["would be feeling","would have felt","will feel","had felt"],"answer":0,"explanation":"This is a mixed conditional: a past condition ('had taken ... yesterday') with a present result ('now'), so the main clause takes 'would + verb'. 'Would have felt' refers to the past and clashes with 'now'.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · IBPS PO"}
];

export default questions;
